import fs from 'node:fs/promises';
import path from 'node:path';

export interface FileProcessingResult {
  file: string;
  status: 'fulfilled' | 'rejected';
  size?: number;
  error?: Error;
}

export async function processFilesConcurrently(
  dirPath: string,
  concurrencyLimit: number = 4
): Promise<FileProcessingResult[]> {
  const entries = await fs.readdir(dirPath, { withFileTypes: true });
  const fileNames = entries.filter(e => e.isFile()).map(e => path.join(dirPath, e.name));

  const results: FileProcessingResult[] = [];
  const executing: Promise<void>[] = [];

  for (const file of fileNames) {
    const p = (async () => {
      try {
        const stat = await fs.stat(file);
        results.push({ file, status: 'fulfilled', size: stat.size });
      } catch (err) {
        results.push({ file, status: 'rejected', error: err as Error });
      }
    })();

    executing.push(p);
    if (executing.length >= concurrencyLimit) {
      await Promise.race(executing);
    }
  }

  await Promise.allSettled(executing);
  return results;
}
